<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();$aid=(int)current_user()['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);if(($_POST['action']??'')==='save')db()->prepare('INSERT INTO saving_tip_templates(created_by_user_id,title,tip_text,rationale_text,base_priority,is_active) VALUES(?,?,?,?,?,TRUE)')->execute([$aid,trim($_POST['title']),trim($_POST['tip_text']),trim($_POST['rationale_text']??''),(float)$_POST['base_priority']]);else db()->prepare('UPDATE saving_tip_templates SET is_active=IF(is_active=1,0,1) WHERE template_id=?')->execute([(int)$_POST['template_id']]);flash('success','Tip template updated.');redirect('admin/tips.php');}$rows=db()->query('SELECT * FROM saving_tip_templates ORDER BY base_priority DESC,created_at DESC')->fetchAll();$pageTitle='Tip Templates';$activePage='tips';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">SAVING ENGINE</span><h1>Tip templates</h1><p>Manage reusable saving guidance.</p></div></section><div class="two-column"><section class="panel"><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><label>Title<input class="input" name="title" required></label><label>Tip<textarea class="input" rows="4" name="tip_text" required></textarea></label><label>Rationale<textarea class="input" rows="3" name="rationale_text"></textarea></label><label>Priority<input class="input" type="number" name="base_priority" value="50"></label><button class="btn btn-primary">Add template</button></form></section><section class="panel"><?php foreach($rows as$t):?><div class="saved-card"><div class="row-between"><strong><?=e($t['title'])?></strong><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="template_id" value="<?=$t['template_id']?>"><button class="text-button"><?=$t['is_active']?'Disable':'Enable'?></button></form></div><p><?=e($t['tip_text'])?></p></div><?php endforeach;?></section></div><?php require __DIR__.'/../includes/footer.php';?>